-- Supplemental export for the 20 Kalahandi Presentation Demo Farm FPO connections.
-- Execute AFTER kalahandi_presentation_demo_20_farms_with_analysis.sql and required schema/master-data migrations.
-- Contains the active farmer-approved relationships, consent records, relationship events, FPO decision audit records,
-- and refreshed FPO portfolio read-model rows. No credentials are included.
BEGIN;
SET LOCAL search_path = public, pg_catalog;
DO $relationship_guard$ BEGIN IF (SELECT count(*) FROM public.farms WHERE farm_id=ANY(ARRAY['53b10e3a-aa27-488f-9e35-40816a482bfa'::uuid, '6f5425c9-20f8-4dc5-adf0-1ca1fadf8ed0'::uuid, '1321d01d-e553-412a-9b93-296c6754f996'::uuid, 'e3576803-966f-4b54-bf01-df48ad10b528'::uuid, '6330b8cf-e6db-4d79-be50-fa2d09e2ba9a'::uuid, '8704e649-656f-48b4-a493-1b7e1ba81ecc'::uuid, '90ddc75b-735c-4348-93de-32a86e8a0105'::uuid, '50583c00-f3c9-4fbd-bce2-e13f394619a1'::uuid, 'e55cef62-39f5-4f91-88be-e05dfac5499c'::uuid, 'dcee0019-7e58-4a00-8157-c74b9657e0ec'::uuid, '613a6591-efd9-463f-a0c3-5b1e9c5675ae'::uuid, 'ce267931-644c-451a-a8f5-63338ffe11fd'::uuid, '9eebf1e4-a7d0-410d-9f3c-970316d4fb76'::uuid, '1b737a6b-6e0f-4a89-b2ce-61a44dcd5593'::uuid, '7090c20e-fb8b-4fd5-8b4c-a3b297ed48ba'::uuid, '7b431ffb-9613-4390-b678-4d618a13bd17'::uuid, '158a5540-38fb-44af-a568-8de8c1177982'::uuid, 'be273b3a-c855-42ff-af03-b8f1ca280f5a'::uuid, 'f281853a-8587-4f4f-bf99-1a93c02532c2'::uuid, '5def420a-4617-4454-9680-033da300fb90'::uuid]::uuid[])) <> 20 THEN RAISE EXCEPTION 'Run the base farm export first; 20 demo farms are required'; END IF; IF (SELECT count(*) FROM public.farmer_profiles WHERE farmer_id=ANY(ARRAY['028878d9-d18c-4418-85a8-8cce3d3d85a9'::uuid, '3f35ca8f-5eb2-4eab-b902-b197dbac391f'::uuid, '8bdfeab0-68f5-4a9d-9563-ec1326628a5d'::uuid, 'f4fd89af-d9b3-4158-b823-45965802cdd6'::uuid]::uuid[])) <> 4 THEN RAISE EXCEPTION 'Required farmer profiles are missing'; END IF; IF (SELECT count(*) FROM public.fpo_organizations WHERE fpo_id=ANY(ARRAY['512cf38e-2203-491f-abb8-6e6c82b45e1e'::uuid]::uuid[])) <> 1 THEN RAISE EXCEPTION 'Required FPO organization is missing'; END IF; IF (SELECT count(*) FROM public.users WHERE user_id=ANY(ARRAY['2e596946-5328-4483-9289-05d60688b1e5'::uuid, '8770c28e-11a6-44c6-b5db-4101ab9ab61e'::uuid, 'a5477d1f-47c5-49d0-ab3f-7d1e3af2400f'::uuid, 'e4737f36-91fe-4d0c-8f29-dfbe5bf1ff27'::uuid, 'f9c7d2ed-e183-40dd-8828-446abf9be0c4'::uuid]::uuid[])) <> 5 THEN RAISE EXCEPTION 'Required farmer/FPO user accounts are missing'; END IF; END $relationship_guard$;

-- fpo_farmer_relationships: 20 row(s)
ON CONFLICT DO NOTHING;

-- fpo_farmer_relationship_consents: 20 row(s)
ON CONFLICT DO NOTHING;

-- fpo_farmer_relationship_events: 60 row(s)
ON CONFLICT DO NOTHING;

-- fpo_audit_events: 20 row(s)
ON CONFLICT DO NOTHING;

-- fpo_farmer_portfolio: 4 refreshed row(s)
ON CONFLICT (fpo_id, farmer_id) DO UPDATE SET "farmer_name"=EXCLUDED."farmer_name", "phone_masked"=EXCLUDED."phone_masked", "district_code"=EXCLUDED."district_code", "district_name"=EXCLUDED."district_name", "block_code"=EXCLUDED."block_code", "block_name"=EXCLUDED."block_name", "village_name"=EXCLUDED."village_name", "farm_count"=EXCLUDED."farm_count", "area_acres"=EXCLUDED."area_acres", "active_crop_codes"=EXCLUDED."active_crop_codes", "condition_status"=EXCLUDED."condition_status", "highest_alert_severity"=EXCLUDED."highest_alert_severity", "open_alert_count"=EXCLUDED."open_alert_count", "latest_observation_at"=EXCLUDED."latest_observation_at", "latest_analysis_date"=EXCLUDED."latest_analysis_date", "relationship_status"=EXCLUDED."relationship_status", "updated_at"=EXCLUDED."updated_at";

-- fpo_portfolio_summary: 1 refreshed row(s)
ON CONFLICT (fpo_id) DO UPDATE SET "active_farmer_count"=EXCLUDED."active_farmer_count", "pending_farmer_count"=EXCLUDED."pending_farmer_count", "active_farm_count"=EXCLUDED."active_farm_count", "registered_area_acres"=EXCLUDED."registered_area_acres", "active_crop_count"=EXCLUDED."active_crop_count", "district_count"=EXCLUDED."district_count", "block_count"=EXCLUDED."block_count", "village_count"=EXCLUDED."village_count", "open_alert_count"=EXCLUDED."open_alert_count", "attention_farm_count"=EXCLUDED."attention_farm_count", "critical_farm_count"=EXCLUDED."critical_farm_count", "data_through"=EXCLUDED."data_through", "calculation_version"=EXCLUDED."calculation_version", "updated_at"=EXCLUDED."updated_at";

COMMIT;
